package com.ecom.notifications.dtos;

import lombok.Getter;
import lombok.Setter;

import java.util.Map;

/**
 * Event envelope. Kept identical to the planned Kafka message format, so producers and this service only need a
 * transport change when Kafka is introduced (HLD 3.6).
 */
@Getter
@Setter
public class EventDto {
    /** Unique per event, generated by the producer; used to drop duplicates */
    private String eventId;
    private String type;
    private long occurredAt;
    /** Event-specific fields; always includes userId, and email/name for User Service events */
    private Map<String, Object> data;
}
